mapper.select:
SELECT id, owner_id, owner_name, slug, title, topic, status, max_participants, control_mode, interaction_version, created_at, closed_at
FROM voice_room
WHERE owner_id = #{ownerId}
AND id < #{beforeId}
ORDER BY id DESC
LIMIT #{sizePlusOne}

mapper.update:
UPDATE voice_room
SET status = 'OPEN', provider_room_name = #{providerRoomName}
WHERE id = #{id} AND status = 'PROVISIONING'
